import{_ as d,o as e,c as a,a3 as r}from"./chunks/framework.BPaanrMb.js";const c=JSON.parse('{"title":"仿真、回放与验证","description":"说明各验证层级能证明什么、不能证明什么，并定义安全声明边界。","frontmatter":{"title":"仿真、回放与验证","description":"说明各验证层级能证明什么、不能证明什么，并定义安全声明边界。","content_type":"knowledge","status":"设计建议","scope":"自动驾驶验证与确认策略","keywords":["仿真","回放","SIL","HIL","封闭场地","安全论证"],"evidence_ids":[]},"headers":[],"relativePath":"knowledge/validation.md","filePath":"knowledge/validation.md","lastUpdated":1794551845000}'),o={name:"knowledge/validation.md"};function n(s,t,l,i,p,_){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="仿真、回放与验证" tabindex="-1">仿真、回放与验证 <a class="header-anchor" href="#仿真、回放与验证" aria-label="Permalink to &quot;仿真、回放与验证&quot;">​</a></h1><p><strong>状态：</strong> <code>设计建议</code> · <strong>仓库事实：</strong> 路线图列出了 Carla 集成、可视化和调试工具方向</p><p>路线图列出 Carla 集成、可视化和调试工具方向。验证结论必须注明层级：</p><table tabindex="0"><thead><tr><th>层级</th><th>能说明什么</th><th>不能说明什么</th></tr></thead><tbody><tr><td>单元/接口测试</td><td>数据结构和局部逻辑符合预期</td><td>系统级实时性和安全性</td></tr><tr><td>离线回放</td><td>在固定数据和配置下可重复</td><td>在线时钟、驱动和执行器问题</td></tr><tr><td>仿真/SIL</td><td>场景行为和接口联调</td><td>真实传感器噪声、底盘动力学和道路风险</td></tr><tr><td>HIL</td><td>实验室条件下的软硬件时序和接口</td><td>未建模的场地风险和整车行为</td></tr><tr><td>封闭场地</td><td>指定车辆与场景的实测表现</td><td>未覆盖场景和量产安全</td></tr><tr><td>受控运营/公开道路/量产</td><td>经批准的运营范围内的运行证据</td><td>对其他车辆、版本和法规环境的普遍保证</td></tr></tbody></table><p>每次实验都应保留版本、配置、场景、随机种子（如有）、数据来源、指标、失败样本和结论边界。仿真、回放和封闭场地结果可以累积证据，但不能互相替代。</p><p>安全相关项目还应把 <a href="https://www.iso.org/standard/68383.html" target="_blank" rel="noreferrer">ISO 26262</a> 功能安全、<a href="https://www.iso.org/standard/77490.html" target="_blank" rel="noreferrer">ISO 21448</a> SOTIF，以及 UL 4600 安全案例方法作为参考框架。引用这些标准不代表 WheelOS 产品或本项目已经获得认证。</p>',6)])])}const f=d(o,[["render",n]]);export{c as __pageData,f as default};
